INSERT INTO `concerns` VALUES (1,'SCF-2026-001',1,0,3,2,1,'ID printing machine not working','The card printer in the student services office is malfunctioning and jamming cards.',NULL,'Low',35,NULL,NULL,120,'2026-11-11 10:32:21','at_risk','2026-11-06 15:32:21',NULL,0,NULL,NULL,NULL,NULL,0,0,'2026-11-06 10:32:21','2026-11-10 15:39:38'),(2,'SCF-2026-002',1,0,1,3,1,'Canteen foods are always cold','Food served in the central canteen warmers is frequently served cold during lunch breaks.',NULL,'Low',28,NULL,NULL,120,'2026-11-08 12:32:21','none','2026-11-03 18:32:21','2026-11-04 16:32:21',0,NULL,NULL,NULL,NULL,0,0,'2026-11-03 12:32:21','2026-11-09 18:32:21'),(3,'SCF-2026-003',1,0,2,3,3,'Clarification about exam schedule','There is an overlap between IT 312 and CS 311 mid-term examination rooms.',NULL,'Medium',52,NULL,NULL,72,'2026-11-08 04:32:21','none','2026-11-06 00:32:21','2026-11-06 00:32:21',0,NULL,NULL,NULL,NULL,0,0,'2026-11-05 04:32:21','2026-11-09 18:32:21'),(4,'SCF-2026-004',1,0,3,1,NULL,'Internet connection issue in Library','Wi-Fi connection drops every 5 minutes on the 2nd floor library study area.',NULL,'Medium',58,NULL,NULL,72,'2026-11-09 10:32:21','breached',NULL,NULL,0,NULL,NULL,NULL,NULL,0,0,'2026-11-06 10:32:21','2026-11-09 18:35:45'),(5,'SCF-2026-005',1,0,1,2,1,'Broken chairs in classroom Lab 2','There are several broken chairs in our classroom Lab 2. It is uncomfortable and unsafe to use. Please kindly address this issue. Thank you.',NULL,'High',78,NULL,NULL,48,'2026-11-10 12:32:21','breached','2026-11-08 16:32:21',NULL,0,NULL,NULL,NULL,NULL,0,0,'2026-11-08 12:32:21','2026-11-10 15:39:38'),(6,'SCF-2026-006',6,0,2,3,3,'Online class attendance error','Attendance in LMS for May 2 meeting marked absent despite submitting activity on time.',NULL,'Medium',45,NULL,NULL,72,'2026-11-03 14:32:21','none','2026-11-01 20:32:21','2026-11-04 08:32:21',0,NULL,NULL,NULL,NULL,0,0,'2026-10-31 14:32:21','2026-11-09 18:32:21'),(7,'SCF-2026-007',5,0,1,1,NULL,'Comfort room is not clean 3rd floor','The 3rd floor west wing comfort room lacks running water and sanitation supplies.',NULL,'Medium',54,NULL,NULL,72,'2026-11-11 22:32:21','none',NULL,NULL,0,NULL,NULL,NULL,NULL,0,0,'2026-11-08 22:32:21','2026-11-09 18:32:21'),(8,'SCF-2026-008',4,0,2,2,3,'Need more reference books for Academic','Library currently has only one copy of Modern Database Systems for 120 enrolled students.',NULL,'Low',32,NULL,NULL,120,'2026-11-12 16:32:21','none','2026-11-08 02:32:21',NULL,0,NULL,NULL,NULL,NULL,0,0,'2026-11-07 16:32:21','2026-11-09 18:32:21'),(9,'SCF-2026-009',2,0,3,2,1,'ID printing machine error','Queuing error in printing machine software causes repeated duplicate student numbers.',NULL,'Medium',50,NULL,NULL,72,'2026-11-10 06:32:21','breached','2026-11-07 12:32:21',NULL,0,NULL,NULL,NULL,NULL,0,0,'2026-11-07 06:32:21','2026-11-10 15:39:38'),(10,'SCF-2026-010',1,0,1,3,1,'Projector not working in Rm 304','The ceiling projector HDMI port in Room 304 is detached. We have a midterm exam presentation there tomorrow morning.',NULL,'High',77,'[\"High impact operational keywords detected: projector not working, projector, exam\",\"Category weight applied: Facilities (+15)\"]',1,48,'2026-11-10 02:32:21','at_risk','2026-11-09 20:46:27','2026-11-09 20:46:27',0,NULL,NULL,NULL,NULL,0,0,'2026-11-08 02:32:21','2026-11-09 20:46:27'),(11,'SCF-2026-011',1,0,1,3,2,'Exposed live wiring and water leak near computer terminals in CCIS Lab 1','Water is dripping from the AC unit directly onto an exposed 220V power extension strip behind PC terminals 12-16. Sparks were observed. Immediate safety hazard!',NULL,'Critical',98,NULL,NULL,24,'2026-11-10 15:32:21','none','2026-11-09 15:47:21','2026-11-09 20:37:51',0,NULL,NULL,NULL,NULL,0,1,'2026-11-09 15:32:21','2026-11-09 20:37:51'),(12,'SCF-2026-012',2,1,4,1,NULL,'Request for counseling schedule during exam week','Several of us in BSCS 2-A are feeling a lot of stress before the midterms. Can the Guidance Office open extra counseling